import sys; from ray import tune; import optax
# This architecture is a standard ConvLSTM, identical to Zephyr I's but with different hparams.
# I can reuse the well-tested network from their public storage.
sys.path.append('storage/zephyr')
from networks.cnn_convlstm_layernorm import CNNConvLSTMLN_Attn

def _define_hyperparameters():
    # Using Cognito I's SOTA-achieving wide CNN features
    return {
        'learning_rate': tune.choice([4e-4]), 'entropy_coef': tune.choice([0.01]),
        'value_loss_coef': tune.choice([0.5]), 
        'cnn_features_1': tune.choice([64]), 
        'cnn_features_2': tune.choice([128]), 
        'conv_lstm_features': tune.choice([64]),
    }

def create_network(hparams):
    return CNNConvLSTMLN_Attn(
        cnn_features_1=hparams['cnn_features_1'], cnn_features_2=hparams['cnn_features_2'],
        conv_lstm_features=hparams['conv_lstm_features'], attn_temp=1.0
    )

def create_optimizer(learning_rate: float = 4e-4):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=learning_rate, weight_decay=1e-4)
    )

BASE_SEED = 90910
